package ai.riskmandate.app.features

import ai.riskmandate.app.features.abpdemo.AbpDemoFeature
import ai.riskmandate.app.features.mandate.MandateFeature
import ai.riskmandate.app.features.site.SiteFeature

/** The summit features, in home-screen order. Owned by the conductor: sessions do not edit this file. */
val FEATURES: List<Feature> = listOf(SiteFeature, AbpDemoFeature, MandateFeature)

fun featureById(id: String): Feature? = FEATURES.firstOrNull { it.id == id }
